import http from 'node:http';

const server = http.createServer((request, response) => {
  console.log('Request:', request.method, request.url);

  if (request.method === 'GET' && request.url === '/about') {
    response.writeHead(200, { 'content-type': 'text/plain; charset=utf-8' });
    response.end('About page');
    return;
  }

  response.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
  response.end('Not found');
});

await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
const base = `http://127.0.0.1:${server.address().port}`;

function get(url) {
  return new Promise((resolve, reject) => {
    http.get(url, { agent: false }, (res) => {
      let body = '';
      res.on('data', (chunk) => { body += chunk; });
      res.on('end', () => resolve({ status: res.statusCode, body }));
    }).on('error', reject);
  });
}

const about = await get(`${base}/about`);
console.log('Status:', about.status);
console.log('Body:', about.body);

const missing = await get(`${base}/nope`);
console.log('Status:', missing.status);
console.log('Body:', missing.body);

server.close();

