function safeFilePath(publicDir, urlPath) {
  const clean = decodeURIComponent(urlPath.split('?')[0]);
  const target = path.normalize(path.join(publicDir, clean));
  if (target !== publicDir && !target.startsWith(publicDir + path.sep)) {
    return null;
  }
  return target;
}

