// main.mjs
import http from 'node:http';

let nextId = 1;
const todos = [];

function sendJson(response, status, data) {
  response.writeHead(status, { 'content-type': 'application/json' });
  response.end(JSON.stringify(data));
}

function readBody(request) {
  return new Promise((resolve, reject) => {
    let body = '';
    request.on('data', (chunk) => { body += chunk; });
    request.on('end', () => resolve(body));
    request.on('error', reject);
  });
}

const server = http.createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');

  if (request.method === 'POST' && url.pathname === '/todos') {
    const body = await readBody(request);
    let data;
    try {
      data = JSON.parse(body);
    } catch {
      sendJson(response, 400, { error: 'invalid JSON' });
      return;
    }
    if (typeof data.title !== 'string' || data.title.trim() === '') {
      sendJson(response, 400, { error: 'title is required' });
      return;
    }
    const todo = { id: nextId, title: data.title.trim(), done: false };
    nextId += 1;
    todos.push(todo);
    sendJson(response, 201, todo);
    return;
  }

  if (request.method === 'GET' && url.pathname === '/todos') {
    sendJson(response, 200, todos);
    return;
  }

  if (request.method === 'PATCH' && url.pathname.startsWith('/todos/')) {
    const id = Number(url.pathname.slice('/todos/'.length));
    const todo = todos.find((item) => item.id === id);
    if (!todo) {
      sendJson(response, 404, { error: 'not found' });
      return;
    }
    todo.done = !todo.done;
    sendJson(response, 200, todo);
    return;
  }

  if (request.method === 'DELETE' && url.pathname.startsWith('/todos/')) {
    const id = Number(url.pathname.slice('/todos/'.length));
    const index = todos.findIndex((item) => item.id === id);
    if (index === -1) {
      sendJson(response, 404, { error: 'not found' });
      return;
    }
    todos.splice(index, 1);
    sendJson(response, 200, { ok: true });
    return;
  }

  sendJson(response, 404, { error: 'route not found' });
});

